      { sku: 'WORKSHOP-DAY', name: 'Brand workshop (day, VAT exempt)', qty: 2, unitPrice: 60000, vatRate: 0, discountPercent: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 5 * 980 + 100 * 50 + 2 * 60000);
  assert.equal(totals.subtotal, 129900);
