import { ok, fail } from './result.js';
import { getCustomer, TIER_DISCOUNTS, normalizeId } from './customers.js';
import { getProduct } from './catalogue.js';
import { nextInvoiceNumber } from './numbering.js';
import { roundCents } from './money.js';
import { isValidDate } from './dates.js';


/**
 * Validate that a quantity is a positive integer.
 * @param {unknown} qty
 * @returns {boolean}
 */
function isValidQty(qty) {
  return Number.isInteger(qty) && qty > 0;
}

/**
 * Validate that a discount percent is a number between 0 and 100.
 * @param {unknown} discountPercent
 * @returns {boolean}
 */
function isValidDiscountPercent(discountPercent) {
  return typeof discountPercent === 'number' && discountPercent >= 0 && discountPercent <= 100;
}

/**
 * Validate that terms are one of the valid options.
 * @param {unknown} terms
 * @returns {boolean}
 */
function isValidTerms(terms) {
  return terms === 'NET14' || terms === 'NET30' || terms === 'EOM';
}

/**
 * Calculate the due date based on terms and issue date.
 * @param {string} issueDate - in YYYY-MM-DD format
 * @param {string} terms - NET14, NET30, or EOM
 * @returns {string} - due date in YYYY-MM-DD format
 */
function calculateDueDate(issueDate, terms) {
  const date = new Date(issueDate + 'T00:00:00Z');

  if (terms === 'NET14') {
    date.setUTCDate(date.getUTCDate() + 14);
  } else if (terms === 'NET30') {
    date.setUTCDate(date.getUTCDate() + 30);
  } else if (terms === 'EOM') {
    const year = date.getUTCFullYear();
    const month = date.getUTCMonth();
    date.setUTCFullYear(year, month + 1, 0);
  }

  const year = date.getUTCFullYear();
  const month = String(date.getUTCMonth() + 1).padStart(2, '0');
  const day = String(date.getUTCDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
}

/**
 * Create an invoice with enriched line items.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number, discountPercent?: number }>, terms?: string }}
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number, discountPercent?: number }>, terms?: string, dueDate?: string } } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines, terms = 'NET30' }) {
  const normalizedCustomerId = normalizeId(customerId);
  const customerResult = getCustomer(normalizedCustomerId);
  if (!customerResult.ok) return customerResult;

  if (!isValidDate(issueDate)) return fail('DATE_INVALID');

  if (!isValidTerms(terms)) return fail('TERMS_INVALID');

  if (!Array.isArray(lines) || lines.length === 0) return fail('NO_LINES');

  const customer = customerResult.value;
  const enrichedLines = [];
  for (const line of lines) {
    if (!isValidQty(line.qty)) return fail('QTY_INVALID');

    if (line.discountPercent !== undefined && !isValidDiscountPercent(line.discountPercent)) {
      return fail('DISCOUNT_INVALID');
    }

    const productResult = getProduct(line.sku);
    if (!productResult.ok) return productResult;

    const product = productResult.value;
    const enrichedLine = {
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
    };
    if (line.discountPercent !== undefined) {
      enrichedLine.discountPercent = line.discountPercent;
    } else {
      enrichedLine.discountPercent = TIER_DISCOUNTS[customer.tier];
    }
    enrichedLines.push(enrichedLine);
  }

  const dueDate = calculateDueDate(issueDate, terms);

  return ok({
    customerId: normalizedCustomerId,
    issueDate,
    status: 'draft',
    terms,
    dueDate,
    lines: enrichedLines,
  });
}

/**
 * Calculate the subtotal for a single line item (qty × unitPrice).
 * @param {{ qty: number, unitPrice: number, discountPercent?: number }}
 * @returns {number}
 */
export function lineTotal(line) {
  const subtotal = line.qty * line.unitPrice;
  return Math.max(0, subtotal);
}

/**
 * Calculate the VAT for a single line item (after discount).
 * @param {{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }}
 * @returns {number}
 */
export function lineVat(line) {
  const subtotal = lineTotal(line);
  const discount = line.discountPercent ? subtotal * line.discountPercent / 100 : 0;
  const amountAfterDiscount = Math.max(0, subtotal - discount);
  const vat = amountAfterDiscount * line.vatRate / 100;
  return roundCents(vat);
}

/**
 * Calculate totals for an invoice.
 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }>, voucher?: { code: string, amount: number } }}
 * @returns {{ subtotal: number, discount: number, vat: number, voucher: number, total: number }}
 */
export function invoiceTotals(invoice) {
  const subtotal = invoice.lines.reduce((sum, line) => sum + lineTotal(line), 0);
  const discount = roundCents(invoice.lines.reduce((sum, line) => {
    const lineSubtotal = lineTotal(line);
    const lineDiscount = line.discountPercent ? lineSubtotal * line.discountPercent / 100 : 0;
    return sum + lineDiscount;
  }, 0));
  const vat = invoice.lines.reduce((sum, line) => sum + lineVat(line), 0);
  const voucher = invoice.voucher ? invoice.voucher.amount : 0;
  const total = Math.max(0, roundCents(subtotal - discount + vat - voucher));
  return {
    subtotal,
    discount,
    vat,
    voucher,
    total,
  };
}

/**
 * Add or increase a line on an invoice.
 * @param {{ status: string, lines: Array<{ sku: string, qty: number, discountPercent?: number }> }} invoice
 * @param {{ sku: string, qty: number, discountPercent?: number }} line
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function addLine(invoice, { sku, qty, discountPercent }) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  if (!isValidQty(qty)) return fail('QTY_INVALID');

  if (discountPercent !== undefined && !isValidDiscountPercent(discountPercent)) {
    return fail('DISCOUNT_INVALID');
  }

  const productResult = getProduct(sku);
  if (!productResult.ok) return productResult;

  const product = productResult.value;
  const newLines = invoice.lines.map((l) => ({ ...l }));
  const existingLineIndex = newLines.findIndex((l) => l.sku === sku);

  if (existingLineIndex >= 0) {
    newLines[existingLineIndex] = {
      ...newLines[existingLineIndex],
      qty: newLines[existingLineIndex].qty + qty,
    };
  } else {
    const newLine = {
      sku,
      name: product.name,
      qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
    };
    if (discountPercent !== undefined) {
      newLine.discountPercent = discountPercent;
    }
    newLines.push(newLine);
  }

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Remove a line from an invoice.
 * @param {{ status: string, lines: Array<{ sku: string }> }} invoice
 * @param {string} sku
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function removeLine(invoice, sku) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  const lineIndex = invoice.lines.findIndex((l) => l.sku === sku);
  if (lineIndex < 0) return fail('LINE_NOT_FOUND');

  if (invoice.lines.length === 1) return fail('NO_LINES');

  const newLines = invoice.lines.filter((l, i) => i !== lineIndex);
  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Issue an invoice, assigning it a number and changing its status.
 * @param {{ status: string, issueDate: string }} invoice
 * @param {Array<string>} existingNumbers
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function issueInvoice(invoice, existingNumbers) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);
  return ok({
    ...invoice,
    number,
    status: 'issued',
  });
}

/**
 * Validate that an amount is a positive integer (in cents).
 * @param {unknown} amount
 * @returns {boolean}
 */
function isValidAmount(amount) {
  return Number.isInteger(amount) && amount > 0;
}

/**
 * Apply a voucher to an invoice.
 * @param {{ status: string, voucher?: object, lines: Array<object> }} invoice
 * @param {{ code: string, amount: number }}
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function applyVoucher(invoice, { code, amount }) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  if (invoice.voucher) return fail('VOUCHER_EXISTS');

  if (!isValidAmount(amount)) return fail('AMOUNT_INVALID');

  return ok({
    ...invoice,
    voucher: { code, amount },
  });
}

