import test from 'node:test';
import assert from 'node:assert/strict';
import { lineTotal, lineVat, invoiceTotals } from '../src/totals.js';

test('lineTotal multiplies qty by unitPrice', () => {
  assert.equal(lineTotal({ qty: 3, unitPrice: 8500 }), 25500);
  assert.equal(lineTotal({ qty: 1, unitPrice: 120000 }), 120000);
  assert.equal(lineTotal({ qty: 10, unitPrice: 50 }), 500);
});

test('lineTotal handles single unit', () => {
  assert.equal(lineTotal({ qty: 1, unitPrice: 9500 }), 9500);
});

test('lineTotal handles zero price', () => {
  assert.equal(lineTotal({ qty: 5, unitPrice: 0 }), 0);
});

test('lineVat calculates VAT on line subtotal', () => {
  const line = { qty: 1, unitPrice: 10000, vatRate: 21 };
  assert.equal(lineVat(line), 2100);
});

test('lineVat calculates VAT on discounted amount', () => {
  const line = { qty: 1, unitPrice: 10000, vatRate: 21, discountPercent: 10 };
  const subtotal = 10000;
  const afterDiscount = subtotal * 0.9;
  const vat = afterDiscount * 0.21;
  assert.equal(lineVat(line), Math.round(vat * 1e6) / 1e6 === 1890 ? 1890 : 1890);
});

test('lineVat with zero VAT rate', () => {
  const line = { qty: 1, unitPrice: 10000, vatRate: 0 };
  assert.equal(lineVat(line), 0);
});

test('lineVat with 9% VAT rate', () => {
  const line = { qty: 1, unitPrice: 10000, vatRate: 9 };
  assert.equal(lineVat(line), 900);
});

test('lineVat rounds to whole cents', () => {
  const line = { qty: 3, unitPrice: 333, vatRate: 21 };
  const subtotal = 999;
  const vat = subtotal * 0.21;
  assert.equal(lineVat(line), 210);
});

test('invoiceTotals sums line totals', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2025-01-15',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 3, unitPrice: 8500, vatRate: 21, discountPercent: 0 },
      { sku: 'DEV-HOUR', name: 'Development (hour)', qty: 2, unitPrice: 9500, vatRate: 21, discountPercent: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 3 * 8500 + 2 * 9500);
  assert.equal(totals.subtotal, 44500);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, Math.round(44500 * 0.21));
  assert.equal(totals.total, 44500 + totals.vat);
});

test('invoiceTotals handles single line', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2025-01-15',
    status: 'draft',
    lines: [{ sku: 'LOGO-PACK', name: 'Logo package', qty: 1, unitPrice: 120000, vatRate: 21, discountPercent: 0 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 120000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 25200);
  assert.equal(totals.total, 145200);
});

test('invoiceTotals handles multiple items with varying quantities', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2025-01-15',
    status: 'draft',
    lines: [
      { sku: 'ICON-SET', name: 'Icon set (24 icons)', qty: 5, unitPrice: 980, vatRate: 21, discountPercent: 0 },
      { sku: 'STICKER', name: 'Sticker sheet', qty: 100, unitPrice: 50, vatRate: 21, discountPercent: 0 },
      { sku: 'WORKSHOP-DAY', name: 'Brand workshop (day, VAT exempt)', qty: 2, unitPrice: 60000, vatRate: 0, discountPercent: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 5 * 980 + 100 * 50 + 2 * 60000);
  assert.equal(totals.subtotal, 129900);
  assert.equal(totals.discount, 0);
  const vatableAmount = 5 * 980 + 100 * 50;
  const vat = Math.round(vatableAmount * 0.21);
  assert.equal(totals.vat, vat);
  assert.equal(totals.total, 129900 + vat);
});

test('invoiceTotals does not mutate the invoice', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2025-01-15',
    status: 'draft',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 3, unitPrice: 8500, vatRate: 21 }],
  };
  const invoiceCopy = JSON.stringify(invoice);
  invoiceTotals(invoice);
  assert.equal(JSON.stringify(invoice), invoiceCopy);
});

test('invoiceTotals returns subtotal, discount, vat, and total', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2025-01-15',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 3, unitPrice: 8500, vatRate: 21, discountPercent: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(typeof totals.subtotal, 'number');
  assert.equal(typeof totals.discount, 'number');
  assert.equal(typeof totals.vat, 'number');
  assert.equal(typeof totals.total, 'number');
  assert.equal(totals.subtotal, 25500);
  assert.equal(totals.discount, 0);
});

test('invoiceTotals calculates discount correctly', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2025-01-15',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 2, unitPrice: 10000, vatRate: 21, discountPercent: 10 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 20000);
  assert.equal(totals.discount, 2000);
  const afterDiscount = 18000;
  const vat = Math.round(afterDiscount * 0.21);
  assert.equal(totals.vat, vat);
  assert.equal(totals.total, afterDiscount + vat);
});

test('invoiceTotals with multiple lines and mixed discounts', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2025-01-15',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 2, unitPrice: 10000, vatRate: 21, discountPercent: 10 },
      { sku: 'DEV-HOUR', name: 'Development (hour)', qty: 3, unitPrice: 15000, vatRate: 21, discountPercent: 0 },
      { sku: 'ICON-SET', name: 'Icon set (24 icons)', qty: 1, unitPrice: 5000, vatRate: 21, discountPercent: 50 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 20000 + 45000 + 5000);
  assert.equal(totals.subtotal, 70000);
  assert.equal(totals.discount, 2000 + 0 + 2500);
  assert.equal(totals.discount, 4500);
});

test('invoiceTotals with 100 percent discount on a line', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2025-01-15',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 2, unitPrice: 10000, vatRate: 21, discountPercent: 100 },
      { sku: 'DEV-HOUR', name: 'Development (hour)', qty: 1, unitPrice: 5000, vatRate: 21, discountPercent: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 25000);
  assert.equal(totals.discount, 20000);
  const vatableAmount = 0 + 5000;
  const vat = Math.round(vatableAmount * 0.21);
  assert.equal(totals.vat, vat);
});

test('invoiceTotals clamps total at 0', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2025-01-15',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 1, unitPrice: 10000, vatRate: 21, discountPercent: 150 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 10000);
  assert.equal(totals.discount, 15000);
  assert.equal(totals.total, 0);
});

test('invoiceTotals with decimal discountPercent', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2025-01-15',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 1, unitPrice: 10000, vatRate: 21, discountPercent: 12.5 },
    ],
  };
  const totals = invoiceTotals(invoice);
