  const afterDiscount = 8750;
  const vat = Math.round(afterDiscount * 0.21);
  assert.equal(totals.vat, vat);
});

test('invoiceTotals includes tier discounts in calculation', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2025-01-15',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 2, unitPrice: 10000, vatRate: 21, discountPercent: 5 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 20000);
  assert.equal(totals.discount, 1000);
  const afterDiscount = 19000;
  const vat = Math.round(afterDiscount * 0.21);
  assert.equal(totals.vat, vat);
});

test('invoiceTotals with different tier discounts across lines', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2025-01-15',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 2, unitPrice: 10000, vatRate: 21, discountPercent: 5 },
