  const totals = invoiceTotals(invoice);
  assert.equal(totals.voucher, 1000);
});

test('invoiceTotals returns 0 voucher when no voucher', () => {
  const invoice = {
    lines: [{ sku: 'DES-HOUR', qty: 1, unitPrice: 10000, vatRate: 21, discountPercent: 0 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.voucher, 0);
});

test('invoiceTotals reduces total by voucher amount', () => {
  const invoice = {
    lines: [{ sku: 'DES-HOUR', qty: 1, unitPrice: 10000, vatRate: 21, discountPercent: 0 }],
    voucher: { code: 'WELCOME10', amount: 1000 },
  };
  const totals = invoiceTotals(invoice);
  const expected = 10000 - 0 + 2100 - 1000;
  assert.equal(totals.total, expected);
});

test('invoiceTotals with voucher and discount', () => {
  const invoice = {
    lines: [{ sku: 'DES-HOUR', qty: 1, unitPrice: 10000, vatRate: 21, discountPercent: 10 }],
    voucher: { code: 'WELCOME10', amount: 500 },
  };
  const totals = invoiceTotals(invoice);
  const subtotal = 10000;
  const discount = 1000;
  const afterDiscount = 9000;
  const vat = 1890;
  const withVoucher = subtotal - discount + vat - 500;
  assert.equal(totals.subtotal, 10000);
  assert.equal(totals.discount, 1000);
  assert.equal(totals.vat, 1890);
  assert.equal(totals.voucher, 500);
  assert.equal(totals.total, withVoucher);
});

test('invoiceTotals clamps total at 0 when voucher exceeds subtotal', () => {
  const invoice = {
    lines: [{ sku: 'DES-HOUR', qty: 1, unitPrice: 1000, vatRate: 0, discountPercent: 0 }],
    voucher: { code: 'HUGE', amount: 10000 },
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.total, 0);
});

